<?php
declare(strict_types=1); requireRole('subject-officer'); require_once __DIR__.'/../../config/database.php'; require_once __DIR__.'/../../includes/activity.php';
$activePage='eligibility-rules';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);
if($_SERVER['REQUEST_METHOD']==='POST'){$categoryId=filter_input(INPUT_POST,'category_id',FILTER_VALIDATE_INT);$months=filter_input(INPUT_POST,'restriction_months',FILTER_VALIDATE_INT);$multiple=isset($_POST['allow_multiple'])?1:0;if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$categoryId)$errors[]='Select a category.';if($months===false||$months<0||$months>1200)$errors[]='Restriction period must be between 0 and 1200 months.';if(!$errors){try{$s=database()->prepare("INSERT INTO eligibility_rules(category_id,restriction_months,allow_multiple,updated_by) VALUES(:category,:months,:multiple,:user) ON DUPLICATE KEY UPDATE restriction_months=VALUES(restriction_months),allow_multiple=VALUES(allow_multiple),updated_by=VALUES(updated_by),status='active'");$s->execute(['category'=>$categoryId,'months'=>$months,'multiple'=>$multiple,'user'=>$_SESSION['user_id']]);logActivity('Eligibility','Updated eligibility restriction','CAT-'.$categoryId);$_SESSION['flash_success']='Eligibility rule saved.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=eligibility-rules');exit;}catch(PDOException $e){error_log($e->getMessage());$errors[]='Unable to save eligibility rule.';}}}
try{$categories=database()->query("SELECT id,name FROM item_categories WHERE status='active' ORDER BY name")->fetchAll();$rows=database()->query('SELECT r.*,c.name category_name,c.distribution_type FROM eligibility_rules r JOIN item_categories c ON c.id=r.category_id ORDER BY c.name')->fetchAll();}catch(PDOException $e){$categories=$rows=[];$errors[]='Eligibility rules are unavailable. Import database/migration_master_data.sql.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Eligibility Rules | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/subject-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Eligibility Rules</h1></div></header><main class="dashboard-content master-config-page"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="admin-data-card"><div class="admin-data-header"><h2>Configure Restriction Period</h2></div><form method="post" class="master-inline-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><label>Aid Category<select name="category_id" required><option value="">Select category</option><?php foreach($categories as $row):?><option value="<?=(int)$row['id']?>"><?=htmlspecialchars($row['name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Restriction Period (Months)<input type="number" name="restriction_months" min="0" max="1200" required></label><label class="master-checkbox"><input type="checkbox" name="allow_multiple"> Allow multiple active items</label><button class="admin-primary-action">Save Rule</button></form></section><section class="admin-data-card master-list-card"><div class="admin-data-header"><h2>Active Eligibility Rules</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table"><thead><tr><th>Category</th><th>Distribution Type</th><th>Restriction</th><th>Multiple Allowed</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="admin-empty-row">No eligibility rules available.</td></tr><?php else:foreach($rows as $row):?><tr><td><strong><?=htmlspecialchars($row['category_name'],ENT_QUOTES,'UTF-8')?></strong></td><td><?=ucwords(str_replace('-',' ',$row['distribution_type']))?></td><td><?=(int)$row['restriction_months']?> months</td><td><?=$row['allow_multiple']?'Yes':'No'?></td><td><?=ucfirst($row['status'])?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
